SELECT kind,encode(sha256(convert_to(versions::text,'UTF8')),'hex') AS digest FROM (SELECT 'entity_types' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.id,t.xmin::text) ORDER BY t.id),'[]') AS versions FROM entity_types t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'workspace_nodes' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.id,t.xmin::text) ORDER BY t.id),'[]') AS versions FROM workspace_nodes t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'workspace_components' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.id,t.xmin::text) ORDER BY t.id),'[]') AS versions FROM workspace_components t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'document_versions' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.id,t.xmin::text) ORDER BY t.id),'[]') AS versions FROM document_versions t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'document_access' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.document_id,t.xmin::text) ORDER BY t.document_id),'[]') AS versions FROM document_access t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'document_controls' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.document_id,t.xmin::text) ORDER BY t.document_id),'[]') AS versions FROM document_controls t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'folder_access' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.folder,t.xmin::text) ORDER BY t.folder),'[]') AS versions FROM folder_access t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'project_records' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.id,t.xmin::text) ORDER BY t.id),'[]') AS versions FROM project_records t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'foundation_functions' AS kind,coalesce(jsonb_agg(jsonb_build_array(t.id,t.xmin::text) ORDER BY t.id),'[]') AS versions FROM foundation_functions t WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'workspaces',coalesce(jsonb_agg(jsonb_build_array(id,xmin::text) ORDER BY id),'[]') FROM workspaces WHERE id=ANY($1::uuid[]) UNION ALL SELECT 'membership',coalesce(jsonb_agg(jsonb_build_array(tenant_id,xmin::text) ORDER BY tenant_id),'[]') FROM memberships WHERE user_id=$2 AND tenant_id IN (SELECT tenant_id FROM workspaces WHERE id=ANY($1::uuid[])) UNION ALL SELECT 'person',coalesce(jsonb_agg(jsonb_build_array(workspace_id,xmin::text) ORDER BY workspace_id),'[]') FROM workspace_access WHERE user_id=$2 AND workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'links',coalesce(jsonb_agg(jsonb_build_array(id,xmin::text) ORDER BY id),'[]') FROM external_links WHERE workspace_id=ANY($1::uuid[]) AND revoked_at IS NULL AND expires_at>now() UNION ALL SELECT 'previews',coalesce(jsonb_agg(jsonb_build_array(id,xmin::text) ORDER BY id),'[]') FROM workspace_previews WHERE workspace_id=ANY($1::uuid[]) AND user_id=$2 AND expires_at>now() UNION ALL SELECT 'schedules',coalesce(jsonb_agg(jsonb_build_array(id,revision_id,paused) ORDER BY id),'[]') FROM foundation_schedules WHERE workspace_id=ANY($1::uuid[]) AND user_id=$2 UNION ALL SELECT 'automations',coalesce(jsonb_agg(jsonb_build_array(id,name,paused,interval_minutes,home_project_id,home_placement_version) ORDER BY id),'[]') FROM automations WHERE workspace_id=ANY($1::uuid[]) UNION ALL SELECT 'app_monitors',coalesce(jsonb_agg(jsonb_build_array(id,app_id,config->>'name',archived_with_app_at,deleted_at) ORDER BY id),'[]') FROM app_monitors WHERE workspace_id=ANY($1::uuid[]) AND user_id=$2 AND archived_with_app_at IS NOT NULL UNION ALL SELECT 'app_actions',coalesce(jsonb_agg(jsonb_build_array(id,app_id,config->>'name',archived_with_app_at,deleted_at) ORDER BY id),'[]') FROM app_actions WHERE workspace_id=ANY($1::uuid[]) AND user_id=$2 AND archived_with_app_at IS NOT NULL) metadata ORDER BY kind
